SELECT s.tenant_id, s.principal_id AS entity_id, GROUP_CONCAT(f.event_id,'|') || '|' || s.event_id AS evidence_ids FROM events s JOIN events f ON f.tenant_id=s.tenant_id AND f.principal_id=s.principal_id AND f.domain='identity' AND f.action='login_failure' AND f.phase=1 AND s.ts-f.ts BETWEEN :min_order_gap AND 300 WHERE s.phase=1 AND s.domain='identity' AND s.action='login_success' AND NOT EXISTS (SELECT 1 FROM events b WHERE b.phase=0 AND b.tenant_id=s.tenant_id AND b.principal_id=s.principal_id AND b.device_id=s.device_id) GROUP BY s.tenant_id,s.principal_id,s.event_id HAVING COUNT(*)>=3;
